# Generated by build.py from recipe.yml for recipe tftp-upload-a-file. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'ro' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'up.cfg'), "hostname r1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'new.cfg'), "hostname r2`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ro/hello.txt'), "hello from surl`n")
cmd /c 'head -c 1300 /dev/zero | tr "\0" a > big.bin'
$server0 = Start-Process surl -ArgumentList '--allow-uploads', '--directory', 'site', 'tftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S -T up.cfg tftp://127.0.0.1:8080/router.cfg } finally { Stop-Process $server0 }
